/// <reference types="cypress" />

// Welcome to Cypress + Argos!

// This spec file is an extract of the first example generated by Cypress.
//
// We have added the `cy.argosScreenshot` command
// provided by the @argos-ci/cypress package to take screenshots.

describe("example to-do app", () => {
  beforeEach(() => {
    cy.visit("https://example.cypress.io/todo");
  });

  it("displays two todo items by default", () => {
    cy.get(".todo-list li").should("have.length", 2);
    cy.get(".todo-list li").first().should("have.text", "Pay electric bill");
    cy.get(".todo-list li").last().should("have.text", "Walk the dog");

    // 👇 That's how we take a screenshot
    cy.argosScreenshot("with two items");
  });

  it("can add new todo items", () => {
    const newItem = "Feed the cat";
    cy.get("[data-test=new-todo]").type(`${newItem}{enter}`);
    cy.get(".todo-list li")
      .should("have.length", 3)
      .last()
      .should("have.text", newItem);

    // 👇 Here, another screenshot is taken
    cy.argosScreenshot("with an added item");
  });
});
